const SEARCH_INPUT_ID="search",SEARCH_RESULTS_ID="search-results",INDEX_URL="/index.json",DEBOUNCE_DELAY=200;let posts=[],timeout=null;window.addEventListener("DOMContentLoaded",async()=>{try{const e=await fetch(INDEX_URL);posts=await e.json(),console.log(`✅ Search index loaded (${posts.length} posts)`)}catch(e){console.error("❌ Failed to load search index:",e)}const e=document.getElementById(SEARCH_INPUT_ID);e&&e.addEventListener("input",e=>{clearTimeout(timeout),timeout=setTimeout(()=>performSearch(e.target.value),DEBOUNCE_DELAY)})});function performSearch(e){const t=getResultContainer();if(t.innerHTML="",!e.trim()){t.style.display="none";return}const n=e.toLowerCase(),s=posts.filter(e=>e.title.toLowerCase().includes(n)||e.description&&e.description.toLowerCase().includes(n));s.length===0?t.innerHTML=`<div class="search-item empty">No results found.</div>`:s.slice(0,10).forEach(e=>{const s=document.createElement("div");s.classList.add("search-item"),s.innerHTML=`
        <a href="${e.url}">
          <strong>${highlightMatch(e.title,n)}</strong>
          ${e.description?`<br><small>${highlightMatch(e.description,n)}</small>`:""}
        </a>`,t.appendChild(s)}),t.style.display="block",t.classList.add("fade-in")}function highlightMatch(e,t){const n=new RegExp(`(${escapeRegExp(t)})`,"gi");return e.replace(n,`<mark>$1</mark>`)}function escapeRegExp(e){return e.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}function getResultContainer(){let e=document.getElementById(SEARCH_RESULTS_ID);return e||(e=document.createElement("div"),e.id=SEARCH_RESULTS_ID,e.className="search-results",document.querySelector(".search-container").appendChild(e)),e}